const root=path.resolve(import.meta.dirname,'..'),base='https://movingfrompuertorico.com',key='6bc5385c-1b5b-4955-bb2e-fc6da8bc924d';
const esc=s=>String(s).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');
const slugify=s=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replaceAll(' ','-');
const link=(slug,label)=>`<a href="/${slug}/">${esc(label)}</a>`;
const section=(title,paragraphs)=>({title,paragraphs});
const states=[
{name:'Florida',city:'Orlando, Tampa, Miami and other Florida destinations',hook:'Florida is a common next chapter, but the receiving address makes each Puerto Rico move different.',arrival:'A waterfront condo, a gated community outside Orlando and a single-family home near Tampa have different delivery arrangements. Give the provider the final address, loading rules and the date your home is ready.',question:'Ask whether the written proposal includes pickup in Puerto Rico, ocean transportation, inland Florida delivery and any requested packing or storage.',detail:'If your Florida housing is not finalized, explain the gap before committing to a receiving date. Ask how a change of address or temporary storage would affect the scope.'},
{name:'New York',city:'New York City, Long Island, Westchester and beyond',hook:'The last few feet of a New York move can require as much planning as the long trip from the island.',arrival:'For apartments, explain elevator bookings, certificate of insurance requests from the building, loading windows and whether the truck can approach the entrance. Suburban and upstate addresses need their own access description.',question:'Ask who will contact you when the shipment is ready for mainland delivery and what receiving window can be offered for your neighborhood.',detail:'If you are staying with family before your new lease starts, keep the essentials you need with you. Discuss any storage or redelivery in writing.'},
{name:'New Jersey',city:'Newark, Jersey City, Bergen County and statewide',hook:'A Puerto Rico to New Jersey move is easiest to quote when the final town and building conditions are known.',arrival:'Share the municipality, floor, elevator or stairs, driveway access and street parking. A Hudson County apartment and a Bergen County home call for different unloading plans.',question:'Confirm whether pickup, ocean leg, mainland delivery, carrying distance and unpacking are included or priced separately.',detail:'If your car travels too, treat it as a separate service question: document condition, pickup/drop-off points and the vehicle arrival plan.'},
{name:'Texas',city:'Houston, Dallas–Fort Worth, San Antonio and more',hook:'Texas is large: the difference between the arrival point and your actual destination can shape the move.',arrival:'Name your destination city and final home, then describe gated access, long driveways, stairs, storage and whether somebody can receive the goods on arrival.',question:'Ask for the mainland delivery portion to be spelled out, including the city, home access and any transfers or storage in between.',detail:'If you are comparing housing in multiple Texas metros, request options for the likely address first and revisit the written scope after the destination is firm.'},
{name:'Pennsylvania',city:'Philadelphia, Pittsburgh, the Lehigh Valley and beyond',hook:'The destination home and neighborhood matter more than a state-wide label on the quote request.',arrival:'In rowhouse areas, share stairs, narrow doors and street loading conditions. Outside cities, provide driveway dimensions and any steep or restricted approach.',question:'Ask which provider handles the final delivery and how you will be updated once the ocean portion is complete.',detail:'Prepare measurements and photos of oversized furniture before shipping. The decision to bring a piece should reflect the doorway and room it must reach.'},
{name:'North Carolina',city:'Charlotte, Raleigh, the Triangle and other communities',hook:'Start with the North Carolina address you plan to use, even if your move date is still flexible.',arrival:'An uptown apartment, suburban home, mountain road and coastal community present different access questions. Mention elevators, gates, stairs and driveway limitations early.',question:'Confirm whether the proposed service ends at the final North Carolina home and what happens if that home is not ready.',detail:'If a family member will receive delivery, identify them and ask the provider what authorization and scheduling information they will need.'},
{name:'Georgia',city:'Atlanta, Savannah and destinations across Georgia',hook:'A clear delivery plan helps connect your Puerto Rico pickup to the Georgia home you are actually moving into.',arrival:'Share apartment loading requirements, elevator reservations, gated community instructions or rural road access. Include a reliable local receiving contact.',question:'Ask for the packing, ocean, inland delivery and optional vehicle pieces to be itemized so you understand the complete move.',detail:'Keep documents, medication and irreplaceable items in your own travel bag rather than assuming you can access shipped boxes mid-route.'},
{name:'Massachusetts',city:'Boston, Worcester and Greater Massachusetts',hook:'Give the mover your Massachusetts destination and the access details behind it.',arrival:'Older apartments may mean tight stairs, short loading windows or building approval. Outside Boston, tell the provider about driveway space, parking and the receiving schedule.',question:'Ask who coordinates delivery after ocean transport and how a delay to your lease or building move-in window is handled.',detail:'Photograph fragile possessions before packing and ask the provider to describe preparation for pieces that require extra protection.'}
];
const origins=[
{name:'San Juan',hook:'A San Juan departure often starts with the building, not the ship.',access:'Tell the provider which neighborhood you are leaving, the floor, elevator availability, concierge or building requirements and whether loading at the entrance is allowed.',inventory:'A tight urban pickup window rewards a complete room-by-room list. Mark pieces that need disassembly, stair carry or special wrapping before discussing service scope.',timing:'Agree on how pickup will be coordinated around building hours and your departure flight. Keep essentials and paperwork with you.'},
{name:'Bayamón',hook:'Describe the home and its approach so the pickup plan matches reality.',access:'Give the neighborhood, driveway and parking details. If the property is inside a gated development, share entry instructions and any restrictions on larger vehicles.',inventory:'Sort large furniture before you request a proposal. Measure pieces against the mainland home and flag storage, stairs and fragile items.',timing:'If closing or lease dates are moving, explain the flexible pickup window and the first date the mainland address can receive delivery.'},
{name:'Carolina',hook:'A Carolina pickup can look different near the airport, along the coast or in a residential community.',access:'Share the exact community, building floor and elevator rules. Coastal condos and gated neighborhoods may require advance notice or a specific loading area.',inventory:'Separate the household inventory from any vehicle request. Ask how each part is prepared, collected and handed off.',timing:'Your flight and housing dates may not align with shipment arrival. Ask about communication, receiving windows and storage options in advance.'},
{name:'Ponce',hook:'A Ponce move needs the actual pickup address and a clear plan for its next handoff.',access:'Describe whether the home is in an urban neighborhood or farther from the center, and mention hills, narrow roads, stairs and available loading space.',inventory:'Build a careful list of large pieces, boxes and items in separate storage before requesting a quote. Ask whether multiple pickup points are available.',timing:'Confirm collection availability for your address and how the schedule connects with the ocean and mainland portions of the move.'}
];
const pages=[];
for(const s of states){const slug='puerto-rico-to-'+s.name.toLowerCase().replaceAll(' ','-');pages.push({slug,title:`Puerto Rico to ${s.name} Moving | Plan Pickup to Delivery`,description:`Plan a move from Puerto Rico to ${s.name}. Understand pickup, ocean transport, mainland delivery and what to include in your quote request.`,eyebrow:'Destination guide',h1:`Moving from Puerto Rico to ${s.name}.`,intro:s.hook,ctaDestination:s.name,sections:[section('Make the route specific',[`Start with your pickup municipality in Puerto Rico and your ${s.name} destination. ${s.arrival}`,s.question]),section('Build an inventory you can discuss',['Room count is a starting point. List large furniture, approximate box count and pieces needing special protection. Mention a vehicle, packing or storage as separate needs. This makes the scope easier to discuss before a provider prepares its written proposal.',s.detail]),section('Understand the handoffs',[`Ask how collection in Puerto Rico connects with the ocean portion and ${s.name} delivery. Find out who communicates at each stage, when updates are available and what you need to do before pickup. The exact route and schedule depend on the provider and service selected.`,'Keep passports or IDs, medication, keys, lease paperwork and daily essentials with you during travel. They should not be packed where you cannot reach them.'])],related:['puerto-rico-moving-cost','puerto-rico-mainland-shipping-process','puerto-rico-moving-checklist']})}
for(const o of origins){const slug='moving-from-'+slugify(o.name);pages.push({slug,title:`Moving From ${o.name}, Puerto Rico | Mainland Guide`,description:`Leaving ${o.name} for the mainland? Plan household pickup, inventory, ocean transport and final delivery with practical questions.`,eyebrow:'Puerto Rico origin',h1:`Moving from ${o.name} to the mainland.`,intro:o.hook,ctaOrigin:o.name,sections:[section('Get pickup details right',[o.access,'Describe any separate storage unit, parking limitation or building reservation when you request options. A provider needs to understand the actual collection point, not just the city.']),section('Decide what will travel',[o.inventory,'Set aside documents, medication and a few days of essentials for your own trip. Make condition notes and photographs for valuable or fragile pieces before packing.']),section('Connect departure with delivery',[o.timing,'Share the final mainland city and home access details. Ask about ocean transportation, the receiving handoff and who will contact you to arrange delivery. Do not treat an early planning estimate as a guaranteed arrival date.'])],related:['puerto-rico-moving-cost','puerto-rico-mainland-shipping-process','puerto-rico-moving-checklist']})}
pages.push(
{slug:'puerto-rico-moving-cost',title:'Moving From Puerto Rico Cost | What Shapes a Quote',description:'Understand the factors behind a Puerto Rico to mainland moving quote: inventory, pickup, ocean leg, destination, vehicle and optional services.',eyebrow:'Planning guide',h1:'What shapes a Puerto Rico moving quote?',intro:'An honest quote starts with your actual shipment and both addresses. There is no useful universal price for every island to mainland move.',sections:[section('The shipment is more than a bedroom count',['A studio can contain oversized furniture and an inventory-heavy apartment can be compact. List the large pieces, approximate box count, fragile items and any specialty handling. Ask the provider what measurement or inventory assumptions are used in the written proposal.']),section('Two homes, multiple stages',['Pickup access in Puerto Rico, preparation, transportation across the water and delivery to your mainland address all need to be understood. Clarify whether the proposal reaches your home or another handoff point. Ask who coordinates each stage and how changes are handled.']),section('Optional work and timing',['Packing, materials, storage and vehicle shipping can change the service scope. Request a clear breakdown and identify which charges are optional. Share your earliest acceptable pickup, arrival flexibility and when the receiving property will be ready. A provider can explain availability for your actual route.']),section('Compare proposals fairly',['Check the same inventory and addresses against each proposal. Look for the provider name, written scope, included work, possible additional charges, valuation or protection terms, and delivery arrangements. A low number without the same scope is not a useful comparison.'])],related:['puerto-rico-mainland-shipping-process','shipping-a-car-from-puerto-rico','how-it-works']},
{slug:'puerto-rico-mainland-shipping-process',title:'Puerto Rico to Mainland Shipping Process | Moving Guide',description:'Follow the household moving stages from Puerto Rico pickup through preparation, ocean transportation and mainland delivery.',eyebrow:'Process guide',h1:'From your door to your next door.',intro:'A move off the island has handoffs. Know what to ask at each one before your belongings leave your home.',sections:[section('1. Scope the household pickup',['Share the exact Puerto Rico address, building or driveway access, inventory and requested pickup range. Ask which team handles collection and whether packing and disassembly are included. If a vehicle is involved, identify it separately.']),section('2. Prepare the shipment',['Confirm who provides packing materials, how fragile pieces are protected and how the inventory is documented. Keep travel essentials and important papers apart from the goods being transported. Ask for the procedure if something must be changed after the inventory is agreed.']),section('3. Confirm ocean and mainland handoffs',['Ask how the shipment moves through the ocean portion, what status updates to expect and who is responsible for scheduling mainland delivery. The specific routing and schedule depend on the provider; avoid assuming that a port arrival is the same day as home delivery.']),section('4. Receive and check',['Prepare the destination address, loading permission, contact person and any elevator reservation. At delivery, compare items against the inventory and follow the provider’s instructions for documenting any concern. Keep copies of the written proposal and service documents.'])],related:['puerto-rico-moving-cost','puerto-rico-moving-checklist','shipping-a-car-from-puerto-rico']},
{slug:'shipping-a-car-from-puerto-rico',title:'Shipping a Car From Puerto Rico | Mainland Planning',description:'Plan vehicle shipping from Puerto Rico to the mainland with questions about handoffs, preparation, documents and pickup.',eyebrow:'Vehicle guide',h1:'Bringing your car from Puerto Rico?',intro:'A vehicle deserves its own written plan alongside your household move.',sections:[section('Decide how the vehicle fits the move',['Tell the provider the year, make, model and whether the car operates normally. State where it is in Puerto Rico and where you want to receive it on the mainland. Ask whether door pickup, terminal drop-off and onward transportation are available for your route.']),section('Prepare before handoff',['Ask the actual vehicle shipping provider for its current preparation, identification and document requirements before you go to a drop-off point. Photograph the vehicle’s condition and keep copies of handoff paperwork. Do not assume household boxes can ride in the vehicle.']),section('Coordinate arrival',['The car and household goods may be handled under separate arrangements. Ask about each delivery point, the notification process, who can collect the car and what changes if your flight or housing date shifts. Get the agreed scope and charges in writing.'])],related:['puerto-rico-mainland-shipping-process','puerto-rico-moving-cost','how-it-works']},
{slug:'puerto-rico-moving-checklist',title:'Puerto Rico to Mainland Moving Checklist | Plan Your Move',description:'A practical checklist for moving from Puerto Rico: inventory, provider questions, building access, documents and delivery preparation.',eyebrow:'Your checklist',h1:'A calmer move starts on paper.',intro:'Save your progress in this browser, then use the list to prepare a useful request and a smoother handoff.',sections:[section('Before you request options',['List furniture and boxes room by room. Decide what stays, what ships and what travels with you. Identify any vehicle, fragile piece or storage need. Write down both addresses and a realistic date range.']),section('Before pickup',['Confirm building or gated access and loading rules at your Puerto Rico home. Ask who handles packing, what documentation you receive and how to update the inventory. Put essentials, medication, IDs, keys and critical documents aside for travel.']),section('Before delivery',['Make sure somebody can receive the shipment at the final mainland address. Confirm parking, elevators, permits or entry codes where relevant. Save your service agreement and ask how the provider shares status updates.'])],related:['puerto-rico-mainland-shipping-process','puerto-rico-moving-cost','how-it-works']},
{slug:'apartment-and-condo-moves-from-puerto-rico',title:'Puerto Rico Apartment & Condo Moves | Mainland Guide',description:'Plan elevator schedules, loading access, packing and final mainland delivery when moving from a Puerto Rico apartment or condo.',eyebrow:'Access guide',h1:'An apartment move has two buildings to plan.',intro:'The best time to find a loading restriction is before your moving day.',sections:[section('At the Puerto Rico home',['Ask management about move hours, elevator reservations, loading spaces and any required notice. Tell your provider about the floor, stairs, walk from unit to vehicle and any furniture that needs disassembly.']),section('At the mainland home',['Check the destination building’s move-in window and loading procedure. Some buildings request advance documentation from the service provider. Give those requirements to the provider before a delivery date is arranged.']),section('If dates do not line up',['A lease ending before your receiving home is available creates a gap. Explain it early and ask about storage, access to stored goods and redelivery in writing. Keep an essentials bag with you so that the gap does not become an emergency.'])],related:['puerto-rico-moving-checklist','puerto-rico-moving-cost','puerto-rico-mainland-shipping-process']},
{slug:'how-it-works',title:'How It Works | MovingFromPuertoRico.com',description:'See what happens after you request a Puerto Rico to mainland moving quote and how a selected provider prepares a written estimate.',eyebrow:'Our process',h1:'Your move, clearly connected.',intro:'Tell us the route and the work you need. We help put your request in front of a suitable moving provider.',sections:[section('Tell us the move',['Enter your Puerto Rico pickup location, mainland destination, timing, move size and best contact details. Include packing, storage, a vehicle or building access in the notes when relevant. There is no charge to submit the request and no obligation to book.']),section('Review and follow-up',['ModelMoving reviews the inquiry and may connect you with a selected moving provider based on route, timing and service needs. ModelMoving or a selected provider may follow up using the contact information and consent you supplied. Availability varies by route.']),section('Discuss the written proposal',['The provider identifies itself, discusses your inventory and service scope, and provides its own estimate and booking documents. Review the company name, services, price terms and delivery arrangements before making a decision. A website request is not a booking.'])],related:['about','puerto-rico-moving-cost','privacy']},
{slug:'faq',title:'Puerto Rico to Mainland Moving FAQs | Answers',description:'Answers to common questions about Puerto Rico pickup, ocean transportation, car shipping, timing and moving quote requests.',eyebrow:'Common questions',h1:'Good questions make better moves.',intro:'Start with what you know. A provider can clarify the details for your address, inventory and schedule.',sections:[section('Will the quote include the whole trip?',['Ask the provider to describe pickup, packing, ocean transportation and final mainland delivery in its written scope. Do not assume a quote covers each stage unless it says so.']),section('Can I move a car too?',['You can indicate a vehicle in your request. Ask about availability for your specific route and whether vehicle handling is a separate service, charge and document set.']),section('How soon should I start?',['Begin once your likely addresses and date range are known. Availability and schedules vary, so earlier conversations give you more room to prepare. Do not rely on a fixed transit estimate until your provider confirms its plan.']),section('Who sends the final estimate?',['A selected moving provider supplies its own written estimate and booking agreement after reviewing your move. Make sure the company and services are clear before you accept.']),section('Is requesting options free?',['Yes. Sending a quote request through this website is free and does not obligate you to book a move.'])],related:['how-it-works','puerto-rico-moving-cost','shipping-a-car-from-puerto-rico']},
{slug:'about',title:'About MovingFromPuertoRico.com | ModelMoving',description:'Meet the Puerto Rico to mainland moving planning site operated by ModelMoving and learn how quote requests are handled.',eyebrow:'About the site',h1:'Built for the move between two shores.',intro:'MovingFromPuertoRico.com is a specialty website operated by ModelMoving for people planning a move from Puerto Rico to the U.S. mainland.',sections:[section('Why this site exists',['Leaving an island involves more than choosing a destination state. You need a usable plan for pickup, inventory, transportation and home delivery. These guides focus on those decisions and help you prepare a detailed inquiry.']),section('How requests work',['ModelMoving reviews requests and may connect customers with selected moving providers for availability, pricing and service discussions. The selected provider identifies itself and supplies the estimate, service agreement and transportation arrangements.']),section('Reach us',['Questions about the website or a submitted request? Email <a href="mailto:modelmoving@gmail.com">modelmoving@gmail.com</a>. Avoid sending payment details or identification documents in an initial message.'])],related:['how-it-works','privacy','faq']},
{slug:'privacy',title:'Privacy Policy | MovingFromPuertoRico.com',description:'How MovingFromPuertoRico.com and ModelMoving use moving quote details, contact information, attribution and local planning preferences.',eyebrow:'Website policy',h1:'Privacy and your request.',intro:'MovingFromPuertoRico.com is operated by ModelMoving. This page explains how this website uses information you provide.',sections:[section('Information collected',['A quote request includes the origin, destination, date, move size, name, phone and optional email and notes. You may indicate vehicle, packing or storage needs. The site also records the page you visited, campaign parameters and referring site when available. Please avoid including payment card data, identity documents or other sensitive records in notes.']),section('How information is used and shared',['ModelMoving uses submitted information to respond to your inquiry and may share relevant contact and move details with selected moving providers so they can discuss pricing, availability and service. Those providers have their own privacy practices. Service providers supporting website hosting, form delivery, analytics and request management may process information to provide those functions.']),section('Calls, texts and emails',['By submitting the form with the consent box checked, you agree that ModelMoving and selected moving partners may contact you about this request by phone, text or email. Message and data rates may apply. Consent is not required to purchase services. You can ask us to stop contacting you by replying STOP to a text or writing to the address below; a provider may also have its own opt-out process.']),section('Analytics and browser storage',['The site uses analytics to understand visits and form interactions. It sends page paths and controlled event names, not your quote fields, to analytics. Campaign and referring-site details may be stored for this browser session and included in a submitted request. An optional checklist saves selected tasks in this browser until you clear them; it does not send the checklist to the quote form.']),section('Retention, access and contact',['Inquiry information is retained as needed to handle requests, maintain records and address legal obligations. You may ask about the information you submitted or request correction or deletion where applicable by emailing <a href="mailto:modelmoving@gmail.com">modelmoving@gmail.com</a>. Please identify the email or phone number used in your request so we can locate it. This policy may be updated as the website changes. Last updated September 26, 2026.'])],related:['terms','about','how-it-works']},
{slug:'terms',title:'Terms of Use | MovingFromPuertoRico.com',description:'Website terms covering Puerto Rico moving guides, free quote requests and provider estimates and agreements.',eyebrow:'Website policy',h1:'Terms of use.',intro:'These terms describe the information and quote request service on MovingFromPuertoRico.com.',sections:[section('Planning information',['Guides and interactive tools are general planning information. They do not provide a binding price, schedule, availability guarantee or individualized transportation advice. Confirm actual requirements and service terms with the provider handling your move.']),section('Requests and provider agreements',['A website request is free and does not create a booking. ModelMoving may review the inquiry and connect you with a selected moving provider. A provider identifies itself and issues its own estimate, contract and service terms. Review those documents before you commit.']),section('Using the website',['Provide accurate contact and move details and do not submit someone else’s information without authority. Automated misuse and false requests may be blocked. Website text and design may not be republished without permission.']),section('Questions and changes',['Contact <a href="mailto:modelmoving@gmail.com">modelmoving@gmail.com</a> with questions about the website. The terms may change as the service evolves. Last updated September 26, 2026.'])],related:['privacy','about','how-it-works']}
);
const titleMap=new Map(pages.map(p=>[p.slug,p.h1]));
function head(title,description,slug='',lang='en'){const url=base+(slug?`/${slug}/`:'/');const alternate=(slug===''||slug==='es')?`<link rel="alternate" hreflang="en" href="${base}/"><link rel="alternate" hreflang="es" href="${base}/es/"><link rel="alternate" hreflang="x-default" href="${base}/">`:'';const schema={"@context":"https://schema.org","@graph":[{"@type":"WebSite","@id":base+'/#website',url:base+'/',name:'MovingFromPuertoRico.com'},...(!slug?[{"@type":"Organization","@id":base+'/#organization',name:'ModelMoving',url:'https://modelmoving.com/'}]:[]),{"@type":"WebPage","@id":url+'#webpage',url,name:title,description,isPartOf:{"@id":base+'/#website'}},...(!slug?[]:[{"@type":"BreadcrumbList",itemListElement:[{"@type":"ListItem",position:1,name:'Home',item:base+'/'},{"@type":"ListItem",position:2,name:title,item:url}]}])]};return `<!doctype html><html lang="${lang}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(title)}</title><meta name="description" content="${esc(description)}"><link rel="canonical" href="${url}">${alternate}<meta name="theme-color" content="#102b33"><meta property="og:type" content="website"><meta property="og:title" content="${esc(title)}"><meta property="og:description" content="${esc(description)}"><meta property="og:url" content="${url}"><meta property="og:site_name" content="MovingFromPuertoRico.com"><meta property="og:image" content="${base}/assets/sanjuan-coast.webp"><meta name="twitter:card" content="summary_large_image"><link rel="icon" href="/assets/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="/assets/site.css"><script type="application/ld+json">${JSON.stringify(schema).replaceAll('<','\\u003c')}</script><script defer src="/assets/analytics.js"></script><script defer src="/assets/site.js"></script></head>`}
function header(lang='en'){const es=lang==='es';return `<body><a class="skip" href="#main">${es?'Ir al contenido':'Skip to content'}</a><header class="site-header"><div class="wrap header-inner"><a class="brand" href="/" aria-label="Moving From Puerto Rico home"><span class="brand-icon" aria-hidden="true">↗</span><span>Moving From Puerto Rico<small>${es?'Un nuevo comienzo':'A new chapter'}</small></span></a><button class="menu" id="menu" aria-controls="navigation" aria-expanded="false">${es?'Menú':'Menu'}</button><nav class="nav" id="navigation" aria-label="Main navigation"><a href="/#explore">${es?'Rutas':'Explore routes'}</a><a href="/puerto-rico-moving-cost/">${es?'Costos':'Moving costs'}</a><a href="/puerto-rico-moving-checklist/">${es?'Lista':'Checklist'}</a><a href="${es?'/':'/es/'}">${es?'English':'Español'}</a><a class="btn small" href="${es?'/es/#quote':'/#quote'}">${es?'Pedir opciones ↗':'Request options ↗'}</a></nav></div></header>`}
function footer(lang='en'){const es=lang==='es';return `<footer class="site-footer"><div class="wrap"><div class="footer-grid"><div><div class="eyebrow">Moving From Puerto Rico</div><h2>${es?'Tu próximo capítulo empieza aquí.':'Your next chapter starts here.'}</h2><p>${es?'Guías de mudanza y solicitudes de cotización operadas por ModelMoving.':'Puerto Rico to mainland planning guides and quote requests operated by ModelMoving.'}</p></div><div><h3>${es?'Planifica':'Plan your move'}</h3>${link('puerto-rico-moving-cost','Moving costs')}${link('puerto-rico-mainland-shipping-process','The moving process')}${link('shipping-a-car-from-puerto-rico','Vehicle shipping')}${link('faq','FAQs')}</div><div><h3>${es?'Acerca de':'About & contact'}</h3>${link('how-it-works','How it works')}${link('about','About')}${link('privacy','Privacy')}${link('terms','Terms')}<a href="mailto:modelmoving@gmail.com">modelmoving@gmail.com</a></div></div><div class="footer-bottom">© 2026 MovingFromPuertoRico.com · Operated by ModelMoving. A quote request is free; the selected moving provider supplies its own estimate and agreement.</div></div></footer><a class="mobile-cta" href="${es?'/es/#quote':'/#quote'}">${es?'Solicitar opciones ↗':'Request moving options ↗'}</a></body></html>`}
function form(es=false){const l=(a,b)=>es?b:a;return `<div class="form-card"><ol class="steps" aria-label="Form progress"><li aria-current="step"></li><li></li><li></li></ol><h3 id="form-heading" tabindex="-1">${l('Where is your move going?','¿Desde dónde te mudas?')}</h3><form id="quote-form" action="https://api.web3forms.com/submit" method="POST"><input type="hidden" name="access_key" value="${key}"><input type="hidden" name="subject" value="New MovingFromPuertoRico.com Quote Request"><input type="hidden" name="source" value="MovingFromPuertoRico.com"><input type="hidden" name="source_site" value="movingfrompuertorico.com"><input type="hidden" name="lead_type" value="Puerto Rico to Mainland Moving Quote Request"><input type="hidden" name="route_page" value="/"><input type="checkbox" class="honeypot" name="botcheck" tabindex="-1" autocomplete="off" aria-hidden="true"><div data-step><p class="form-help">${l('Start with the island pickup and your mainland destination.','Comienza con el lugar de recogida en la isla y tu destino continental.')}</p><div class="pill-row" role="group" aria-label="Popular Puerto Rico origins">${['San Juan','Bayamón','Carolina','Ponce'].map(n=>`<button type="button" class="pill" data-origin="${n}" aria-pressed="false">${n}</button>`).join('')}</div><div class="fields"><div class="field"><label for="moving_from">${l('Puerto Rico pickup city or ZIP','Ciudad o código postal de origen')} *</label><input id="moving_from" name="moving_from" autocomplete="address-level2" required placeholder="${l('San Juan, PR','San Juan, PR')}"></div><div class="field"><label for="moving_to">${l('Mainland destination city or ZIP','Ciudad o código postal de destino')} *</label><input id="moving_to" name="moving_to" required placeholder="${l('Orlando, FL','Orlando, FL')}"></div><div class="field"><label for="move_date">${l('Estimated move date','Fecha estimada de mudanza')} *</label><input id="move_date" type="date" name="move_date" required></div><div class="field"><label for="move_size">${l('Move size','Tamaño de la mudanza')} *</label><select id="move_size" name="move_size" required><option value="">${l('Select one','Selecciona')}</option><option>Studio / 1 Bedroom</option><option>2 Bedroom</option><option>3 Bedroom</option><option>4+ Bedroom</option><option>Vehicle / Specialty Item</option><option>Not sure yet</option></select></div></div><div class="form-actions"><button type="button" class="btn dark" data-next>${l('Continue to details →','Continuar →')}</button></div></div><div data-step hidden><p class="form-help">${l('A few details help us understand the right scope.','Estos detalles nos ayudan a entender lo que necesitas.')}</p><div class="fields"><div class="field"><label for="vehicle">${l('Shipping a vehicle?','¿Enviarás un vehículo?')}</label><select id="vehicle" name="vehicle"><option>Not sure</option><option>Yes</option><option>No</option></select></div><div class="field"><label for="packing">${l('Packing help?','¿Necesitas ayuda para empacar?')}</label><select id="packing" name="packing"><option>Not sure</option><option>Yes</option><option>No</option></select></div><div class="field"><label for="storage">${l('Storage needed?','¿Necesitas almacenamiento?')}</label><select id="storage" name="storage"><option>Not sure</option><option>Yes</option><option>No</option></select></div><div class="field full"><label for="notes">${l('Move notes (optional)','Detalles de la mudanza (opcional)')}</label><textarea id="notes" name="notes" placeholder="${l('Stairs, elevators, fragile items, building rules…','Escaleras, ascensores, artículos frágiles…')}"></textarea></div></div><div class="form-actions"><button type="button" class="quiet-button" data-back>${l('← Back','← Atrás')}</button><button type="button" class="btn dark" data-next>${l('Continue to contact →','Continuar →')}</button></div></div><div data-step hidden><p class="form-help">${l('We’ll use this to follow up about your request.','Usaremos estos datos para dar seguimiento a tu solicitud.')}</p><div class="fields"><div class="field full"><label for="full_name">${l('Full name','Nombre completo')} *</label><input id="full_name" name="full_name" autocomplete="name" required></div><div class="field"><label for="phone">${l('Phone number','Teléfono')} *</label><input id="phone" name="phone" type="tel" autocomplete="tel" inputmode="tel" required></div><div class="field"><label for="email">${l('Email (optional)','Correo electrónico (opcional)')}</label><input id="email" name="email" type="email" autocomplete="email"></div></div><label class="consent"><input type="checkbox" name="consent" value="yes" required> ${l('I agree that ModelMoving and selected moving partners may contact me about this quote request by phone, text or email. Message/data rates may apply. Consent is not required to purchase services.','Acepto que ModelMoving y proveedores de mudanza seleccionados puedan contactarme sobre esta solicitud por teléfono, mensaje de texto o correo electrónico. Pueden aplicarse cargos por mensajes y datos. Mi consentimiento no es necesario para comprar servicios.')}</label><p class="form-help">${l('Read our','Lee nuestra')} <a href="/privacy/">${l('privacy policy','política de privacidad')}</a>. ${l('No obligation to book.','Sin obligación de reservar.')}</p><div class="form-actions"><button type="button" class="quiet-button" data-back>${l('← Back','← Atrás')}</button><button type="submit" class="btn" id="form-submit">${l('Request My Moving Options','Solicitar opciones de mudanza')}</button></div></div><div id="form-status" class="status" role="status" tabindex="-1" aria-live="polite"></div></form></div>`}
function page(p){const quoteUrl='/?'+new URLSearchParams({...(p.ctaOrigin?{origin:p.ctaOrigin}:{}),...(p.ctaDestination?{destination:p.ctaDestination}:{}),route_page:`/${p.slug}/`}).toString()+'#quote';const related=p.related.map(slug=>`<li>${link(slug,titleMap.get(slug)||slug)}</li>`).join('');return head(p.title,p.description,p.slug)+header()+`<main id="main"><div class="article-hero"><div class="wrap"><div class="breadcrumb"><a href="/">Home</a> / ${esc(p.eyebrow)}</div><div class="eyebrow" style="margin-top:28px;color:var(--teal)">${esc(p.eyebrow)}</div><h1>${esc(p.h1)}</h1><p class="lede">${esc(p.intro)}</p><a class="btn dark" href="${quoteUrl}">Plan my mainland move ↗</a></div></div><div class="wrap article-grid"><article class="article">${p.sections.map((s,i)=>`<section id="part-${i+1}"><h2>${esc(s.title)}</h2>${s.paragraphs.map(t=>`<p>${t}</p>`).join('')}</section>`).join('')}<div class="inline-callout"><strong>Ready to make it specific?</strong><p>Share your Puerto Rico pickup, mainland address and the services you need. A selected provider can discuss availability and prepare its own written proposal.</p><a href="${quoteUrl}">Request moving options ↗</a></div><h2>Keep planning</h2><ul>${related}</ul></article><aside class="aside"><div class="eyebrow">Quick start</div><h3>Plan with a real route.</h3><p>Tell us what is moving, where it is going and how to reach you.</p><a class="btn" href="${quoteUrl}">Start my request ↗</a><p class="form-help">Free request · No obligation to book</p></aside></div></main>`+footer()}
function home(){const title='Moving From Puerto Rico to the Mainland | MovingFromPuertoRico.com',desc='Plan a Puerto Rico to mainland move with route guides, checklists and a free quote request. Pickup, ocean transportation and final delivery explained.';return head(title,desc)+header()+`<main id="main"><section class="hero"><div class="hero-image" role="img" aria-label="Illustrative coastal view of Old San Juan at sunset"></div><div class="wrap hero-grid"><div><div class="eyebrow" style="color:#ffba9d">PUERTO RICO → YOUR NEXT CHAPTER</div><h1>From the island. <em>Into what’s next.</em></h1><p class="hero-copy">Moving from Puerto Rico to the mainland? Tell us your route, timing and what is coming with you. We’ll help connect your request with a selected moving provider to discuss your options.</p><div class="hero-actions"><a class="btn" href="#quote">Plan my move ↗</a><a class="text-link" href="#explore">Explore destinations ↓</a></div><p class="hero-meta">Free request. No obligation to book. Your selected provider supplies its own written estimate and booking agreement.</p></div><div class="hero-stamp" aria-label="How the move comes together"><div class="eyebrow">Your route, made clearer</div><h2>One journey.<br>Every handoff planned.</h2><div class="route-line"><i>01</i> Puerto Rico pickup</div><div class="route-line"><i>02</i> Ocean transportation</div><div class="route-line"><i>03</i> Mainland home delivery</div><a href="/puerto-rico-mainland-shipping-process/" class="text-link">Understand the process ↗</a></div></div></section><div class="strip"><div class="wrap strip-inner"><span>Puerto Rico focused guides</span><span>Destination-specific planning</span><span>Free quote request</span><span>Real provider follow-up</span></div></div><section id="explore" class="section"><div class="wrap split"><div><div class="eyebrow" style="color:var(--teal)">THE ROUTE EXPLORER</div><h2>Where is your next chapter?</h2><p>Choose a destination to see the first details worth discussing. We’ll carry it into your quote request.</p><div class="journey"><div class="eyebrow">Island → mainland</div><div class="journey-route"><div class="place">Puerto<br>Rico</div><div class="dash"></div><div class="place to" id="journey-to">Florida</div></div><label for="explore-destination">Destination state</label><select id="explore-destination"><option>Florida</option><option>New York</option><option>New Jersey</option><option>Texas</option><option>Pennsylvania</option><option>North Carolina</option><option>Georgia</option><option>Massachusetts</option></select></div></div><div><div class="eyebrow" style="color:var(--teal)">A SMARTER START</div><h3 id="explore-heading" style="font:600 2rem Fraunces,serif">The details change with your destination.</h3><p id="explore-note">Confirm the delivery city and condo or building rules.</p><ul class="feature-list"><li>Share your exact Puerto Rico pickup location.</li><li>Identify the final mainland address and building access.</li><li>Describe packing, storage and any vehicle needs.</li></ul><div class="hero-actions"><button class="btn dark" id="explore-quote" type="button">Plan this route ↗</button><a id="explore-guide" href="/puerto-rico-to-florida/">Read the Florida guide</a></div></div></div></section><section class="section alt"><div class="wrap"><div class="section-head"><div class="eyebrow" style="color:var(--teal)">GOOD MOVES START WITH THE RIGHT QUESTIONS</div><h2>Know the move before you commit.</h2><p>The island departure, transportation and final mainland address all shape your plan. Here is where to start.</p></div><div class="card-grid"><article class="card"><span class="num">01 / PREPARE</span><h3>Build the real inventory</h3><p>List furniture, boxes, fragile items and what will travel separately. Better details make the provider conversation more useful.</p><a href="/puerto-rico-moving-checklist/">Open your checklist ↗</a></article><article class="card"><span class="num">02 / CONNECT</span><h3>Understand the handoffs</h3><p>Ask who manages pickup, what happens during the ocean leg and who arranges mainland delivery to your home.</p><a href="/puerto-rico-mainland-shipping-process/">Explore the journey ↗</a></article><article class="card"><span class="num">03 / DECIDE</span><h3>Review written scope</h3><p>Compare the actual services, company name, destination and possible extra charges before accepting a proposal.</p><a href="/puerto-rico-moving-cost/">See cost factors ↗</a></article></div></div></section><section class="section"><div class="wrap"><div class="section-head"><div class="eyebrow" style="color:var(--teal)">POPULAR MAINLAND DESTINATIONS</div><h2>Where are you headed?</h2><p>Use a destination guide, then share your exact city and address for the request.</p></div><div class="route-cards">${states.map(s=>`<a class="route-card" href="/puerto-rico-to-${s.name.toLowerCase().replaceAll(' ','-')}/"><span>Puerto Rico →</span>${esc(s.name)} <span aria-hidden="true">↗</span></a>`).join('')}</div><p style="margin-top:23px">Leaving from a particular city? ${origins.map(o=>link('moving-from-'+slugify(o.name),o.name)).join(' · ')}</p></div></section><section class="section alt" id="tools"><div class="wrap"><div class="section-head"><div class="eyebrow" style="color:var(--teal)">YOUR PLANNING DESK</div><h2>Make the next steps yours.</h2><p>Try the planning tools. They offer prompts, not prices or promised delivery dates.</p></div><div class="tools-grid"><div class="tool"><div class="eyebrow" style="color:var(--teal)">QUOTE CLARITY</div><h3>What changes the scope?</h3><label for="cost-factor">Choose a factor</label><select id="cost-factor"><option>Inventory</option><option>Pickup</option><option>Delivery</option><option>Services</option><option>Timing</option></select><div class="tool-output" id="cost-factor-output"></div><p><a href="/puerto-rico-moving-cost/">Understand moving costs ↗</a></p></div><div class="tool"><div class="eyebrow" style="color:var(--teal)">PREPARATION WINDOW</div><h3>Work backward from your date.</h3><p>Enter a target departure date for three suggested preparation reminders.</p><label for="target-date">Target move date</label><input id="target-date" type="date"><div class="tool-output" id="timeline-output" aria-live="polite">Choose a date to see planning reminders. Confirm actual pickup and delivery with your provider.</div><p><a href="/puerto-rico-moving-checklist/">Open the full checklist ↗</a></p></div><div class="tool"><div class="eyebrow" style="color:var(--teal)">YOUR MOVE BOARD</div><h3>Keep track of the essentials.</h3><ul class="check-list"><li><label><input type="checkbox" data-check="inventory"> List furniture and boxes</label></li><li><label><input type="checkbox" data-check="pickup"> Check pickup access</label></li><li><label><input type="checkbox" data-check="destination"> Confirm destination address</label></li><li><label><input type="checkbox" data-check="vehicle"> Decide on vehicle shipping</label></li><li><label><input type="checkbox" data-check="essentials"> Set aside travel essentials</label></li></ul><p id="check-status" aria-live="polite">0 / 5 tasks complete</p><button class="quiet-button" type="button" id="reset-checks">Reset my list</button><p class="form-help">Saved in this browser only.</p></div><div class="tool" style="background:var(--navy);color:white"><div class="eyebrow" style="color:#abdbd1">THE IMPORTANT PART</div><h3 style="font-size:2.1rem">You decide what happens next.</h3><p style="color:#d7e9e5">Your request starts a conversation. A selected provider identifies itself and supplies its own written estimate and agreement. You can ask questions before you book.</p><a class="btn" href="#quote">Start my request ↗</a></div></div></div></section><section id="quote" class="section dark"><div class="wrap form-shell"><div class="form-intro"><div class="eyebrow" style="color:#ffba9d">THE NEXT CHAPTER FORM</div><h2>Tell us the route. We’ll help with the next step.</h2><p>Start with your Puerto Rico pickup and mainland destination. Add a few details, then tell us the best way to reach you.</p><ul class="feature-list"><li>Three short steps</li><li>Vehicle and packing needs captured</li><li>No obligation to book</li></ul><p class="form-help" style="color:#c5e4df">Questions first? <a href="mailto:modelmoving@gmail.com">Email ModelMoving</a>.</p></div>${form()}</div></section><section class="section"><div class="wrap split"><div><div class="eyebrow" style="color:var(--teal)">CLEAR ROLES, CLEAR NEXT STEPS</div><h2>Here’s what happens after you click.</h2><p>ModelMoving reviews your request and may connect you with a selected moving provider for your route and needs. That provider discusses the service, identifies its company and supplies its own written estimate and booking documents.</p><p>We made this site to help you ask better questions before choosing how to move.</p><a class="btn dark" href="/how-it-works/">See how it works ↗</a></div><div class="card"><div class="eyebrow" style="color:var(--teal)">QUESTIONS WORTH ASKING</div><h3>What does the written scope include?</h3><ul class="feature-list"><li>Pickup at my Puerto Rico address?</li><li>Packing and ocean transport?</li><li>Delivery to the final mainland home?</li><li>Storage, vehicle, stairs or elevator service?</li></ul><a href="/faq/">Read the FAQs ↗</a></div></div></section></main>`+footer()}
function spanish(){const title='Mudanzas de Puerto Rico a Estados Unidos | MovingFromPuertoRico.com',description='Planifica tu mudanza de Puerto Rico a Estados Unidos. Solicita opciones de mudanza, prepara tu inventario y conoce los pasos hasta la entrega.';return head(title,description,'es','es')+header('es')+`<main id="main"><section class="hero"><div class="hero-image" role="img" aria-label="Vista ilustrativa de la costa de San Juan al atardecer"></div><div class="wrap hero-grid"><div><div class="eyebrow" style="color:#ffba9d">PUERTO RICO → TU PRÓXIMO CAPÍTULO</div><h1>De la isla. <em>Hacia lo que viene.</em></h1><p class="hero-copy">¿Te mudas de Puerto Rico a Estados Unidos? Cuéntanos desde dónde sales, a dónde llegas y qué necesitas llevar. Te ayudamos a conectar tu solicitud con un proveedor de mudanzas seleccionado.</p><div class="hero-actions"><a class="btn" href="#quote">Planificar mi mudanza ↗</a></div><p class="hero-meta">Solicitar opciones es gratis y no te obliga a reservar. El proveedor entrega su propio estimado y contrato por escrito.</p></div><div class="hero-stamp"><div class="eyebrow">Tu ruta, más clara</div><h2>Una mudanza. Varios pasos.</h2><div class="route-line"><i>01</i> Recogida en Puerto Rico</div><div class="route-line"><i>02</i> Transporte por mar</div><div class="route-line"><i>03</i> Entrega en tu nuevo hogar</div><a href="/puerto-rico-mainland-shipping-process/">Ver la guía en inglés ↗</a></div></div></section><section class="section"><div class="wrap"><div class="section-head"><div class="eyebrow" style="color:var(--teal)">ANTES DE SOLICITAR OPCIONES</div><h2>Prepárate para una conversación útil.</h2><p>Una buena solicitud describe tu mudanza real. Así el proveedor puede hablar contigo sobre el alcance y preparar su propuesta.</p></div><div class="card-grid"><article class="card"><span class="num">01 / ORIGEN</span><h3>Confirma la recogida</h3><p>Indica el municipio, la dirección, las escaleras, el ascensor y cualquier regla de estacionamiento o del edificio.</p></article><article class="card"><span class="num">02 / INVENTARIO</span><h3>Cuenta lo que llevarás</h3><p>Anota muebles grandes, cajas, objetos frágiles y si necesitas ayuda para empacar, almacenamiento o envío de un vehículo.</p></article><article class="card"><span class="num">03 / DESTINO</span><h3>Describe la entrega</h3><p>Comparte la ciudad y las condiciones de acceso a la nueva vivienda. Pregunta qué incluye el estimado escrito.</p></article></div></div></section><section class="section alt"><div class="wrap split"><div><div class="eyebrow" style="color:var(--teal)">PREGUNTAS IMPORTANTES</div><h2>Conoce cada etapa.</h2><p>Pregunta quién recoge tus pertenencias, cómo se coordina el transporte por mar y quién organizará la entrega en tu domicilio continental. Si envías un auto, aclara si tiene un servicio y documentos aparte.</p><p>Guarda tus documentos, medicamentos, llaves y artículos esenciales contigo durante el viaje. Consulta la disponibilidad y las fechas directamente con el proveedor: dependen de la ruta y del servicio elegido.</p></div><div class="card"><h3>Después de enviar tu solicitud</h3><p>ModelMoving la revisa y puede conectarte con un proveedor seleccionado. El proveedor se identifica, habla contigo sobre el inventario y entrega su propio estimado y contrato. Tú decides si deseas continuar.</p><a class="btn dark" href="#quote">Solicitar opciones ↗</a></div></div></section><section id="quote" class="section dark"><div class="wrap form-shell"><div class="form-intro"><div class="eyebrow" style="color:#ffba9d">SOLICITUD DE MUDANZA</div><h2>Cuéntanos tu ruta.</h2><p>Tres pasos cortos para compartir tu origen, destino, necesidades y datos de contacto.</p><p>¿Tienes preguntas? <a href="mailto:modelmoving@gmail.com">Escríbenos</a>.</p></div>${form(true)}</div></section></main>`+footer('es')}
async function save(slug,html){const dir=path.join(root,slug);await mkdir(dir,{recursive:true});await writeFile(path.join(dir,'index.html'),html)}
await writeFile(path.join(root,'index.html'),home());for(const p of pages)await save(p.slug,page(p));await save('es',spanish());
const urls=['',...pages.map(p=>p.slug),'es'];await writeFile(path.join(root,'sitemap.xml'),'<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n'+urls.map(s=>`  <url><loc>${base}/${s?s+'/':''}</loc></url>`).join('\n')+'\n</urlset>\n');
await writeFile(path.join(root,'robots.txt'),`User-agent: *\nAllow: /\nSitemap: ${base}/sitemap.xml\n`);await writeFile(path.join(root,'CNAME'),'movingfrompuertorico.com\n');
await writeFile(path.join(root,'404.html'),head('Page not found | MovingFromPuertoRico.com','That page could not be found.')+header()+`<main id="main" class="section"><div class="wrap"><h1>That route is not on this map.</h1><p>Head back to the Puerto Rico moving guides or start a new request.</p><a class="btn dark" href="/">Return home ↗</a></div></main>`+footer());
console.log(`Built ${urls.length} indexable pages plus 404.`);
